window.DOSIK=window.DOSIK||{};DOSIK["yc_family"]={"1":[{"t":"table","title":"가족체계 개념","head":["개념","내용"],"rows":[["거짓상호성","겉으로 드러난 가족원간의 친밀한 상호작용이 사실과 다른 모습이다"],["고무울타리","가족을 둘러싼 경계가 유동적이나 외부의 영향이 스며들지 않는 것을 말한다"],["이중구속","두 가지 모순된 메시지가 서로 다른 수준에서 전달되는 경우이다"],["삼각관계","두 사람 사이의 불안과 긴장을 해소하기 위하여 다른 사람이나 대상을 관계로 끌어들이는 것이다"],["부적(negative) 피드백","체계가 변화나 이탈을 거부하고 안정성을 유지하는 방향으로의 피드백이다"]]},{"t":"tree","title":"체계이론의 관점","root":"체계이론","branches":[["순환적 인과관계","순환적 인과관계를 통해 문제를 이해하고자 한다 · 순환적 인과관계 속에서 증상을 이해하려고 한다"],["상호 관계성","가족구성원 간의 상호 관계성에 주목한다 · 체계를 구성하는 개인 간 관계에 초점을 두고 개입한다"],["행위의 패턴","가족구성원 간 행위의 연쇄적인 패턴을 파악하고자 한다"],["관계 속 문제","개인을 둘러싸고 있는 관계 속에서 일어나는 문제에 더 많은 관심을 가지고 있다"],["규칙","체계는 일정한 규칙에 의해 유지되고 기능한다"]]}],"2":[{"t":"table","title":"가족생활주기 이론가","head":["이론가","내용"],"rows":[["가족생활주기","가족생활주기의 각 단계마다 수행해야 할 과업을 제시한다"],["듀발(E. Duvall)","결혼, 출산, 자녀 성장, 사망 등 구성원의 증가 또는 감소를 축으로 하여 8단계로 나누었다"],["카터(B. Carter)와 맥골드릭(M. McGoldrick)","가족생활주기의 결혼전기 단계에서 원가족과 분화가 필요하다고 했다"],["에릭슨(M. Erickson)","자녀 양육기의 가족은 부모와 자녀를 분리하여 부부생활과 자녀양육 생활을 독립적으로 하도록 했다"]]},{"t":"flow","title":"자녀 양육기 가족","steps":["자녀의 발달과 변화에 대응하여 부모의 역할도 변해야 한다","자녀가 책임감을 가지도록 가족의 구조와 조직을 변화시킨다","자녀가 가족체계에 자유롭게 출입할 수 있도록 가족의 경계를 유연하게 설정한다","결혼생활 중인 부모는 부부관계의 재적응과 재협상에도 주력한다"]}],"3":[{"t":"cause","title":"분화 수준과 불안","causes":["기본분화 수준이 낮음","부모의 미숙함에 노출되는 자녀"],"result":"만성불안의 수준이 높고 융합의 정도가 높다","effects":["완벽한 분화는 집단 안에서 한 개인이 된다는 것이다"]},{"t":"table","title":"보웬의 개념","head":["개념","내용"],"rows":[["미분화 가족자아군","가족이 감정적으로 한 덩어리가 되어 정서적으로 함께 고착되어 있는 상태를 말한다"],["핵가족 정서체계","핵가족 내에서 가족이 정서적으로 기능하는 패턴을 말한다"],["가족투사과정","부모가 자신들의 미성숙함을 자녀에게 투사하는 과정이다"],["정서적 단절","개인이 불안을 관리하기 위해 가족구성원과 감정적 교류를 더 이상 하지 않는 것이다"],["출생순위","출생순위 또는 형제자매 위치가 가족의 정서체계 안에서 특정한 역할과 기능을 한다"]]},{"t":"flow","title":"치료 목표","steps":["만성불안에 대한 감정반사행동을 줄이는 것을 목표로 한다","가족의 비생산적 관계과정을 변화시키기 위해 관계실험을 한다"]}],"4":[{"t":"table","title":"구조적 가족치료","head":["개념","내용"],"rows":[["가족구조","가족구성원의 상호작용 방식을 조직화하는 보이지 않는 요구가 가족구조를 만든다"],["균형깨기","과대기능하는 모와 과소기능하는 아들 간 위계 조정을 위해 아들 편을 들면서 균형깨기를 한다"],["침투적이고 모호한 경계선","침투적이고 모호한 경계선을 가진 가족은 강한 소속감 때문에 자율성이 방해를 받는다"],["적절한 위계","부모가 권위와 책임을 바탕으로 세대 간 차이를 인정하는 구조이다"]]},{"t":"tree","title":"하위체계의 기능","root":"부모의 역할","branches":[["부모체계","자녀의 발달단계에 맞는 규칙을 설정하고 부모의 권위를 적절히 사용해야 한다"],["부부 하위체계","부모 하위체계와 별도로 부부 하위체계가 기능하도록 한다"],["일관성","부모가 서로 지원하고 서로에게 적응함으로써 자녀에게 일관된 모습을 보여야 한다"],["자녀 갈등","부모는 자녀끼리 협상하고 갈등이나 차이를 해결하도록 지원한다"]]}],"5":[{"t":"table","title":"전략적 가족치료","head":["모델","내용"],"rows":[["헤일리(J. Haley)","고된 체험, 위장 기법 등의 역설적인 방법을 활용한다"],["밀란(Milan) 모델","게임규칙에 초점을 두고 순환질문을 사용한다"],["MRI 모델","Mental Research Institute · 가족의 의사소통에 초점을 두고 전략적으로 접근한다"],["마다네스(C. Madanes)","애정과 돌봄 역할에 관심을 두고 치료 작업을 한다"]]}],"6":[{"t":"table","title":"사티어의 경험적 모델","head":["개념","내용"],"rows":[["경험적 치료과정","내담자의 체험을 중시한다"],["빙산","개인 및 가족의 심리 내적 경험을 이해할 수 있는 지도이다"],["가족규칙","일종의 명령으로 원가족 삼인군의 경험에서 획득하여 내재화한 것이다"],["자아존중감","요소는 자기, 타인, 상황으로 낮은 자아존중감을 회복시키는 것이 목표이다"]]},{"t":"table","title":"상징-경험적 가족상담","head":["구분","내용"],"rows":[["휘태커(C. Whitaker)","상징-경험적 상담의 휘태커는 정서적 과정과 가족구조에 초점을 맞춘다"],["상담자","상징-경험적 가족상담자들은 내담자들과의 관계 구축을 위해 · 따뜻함과 직면을 균형적으로 사용한다"],["내면가족체계치료","원래 트라우마와 학대 생존자들을 위한 치료로 · 체계적 원리를 이용하여 개인의 내적인 부분들과 작업한다"]]},{"t":"tree","title":"경험적 가족상담","root":"경험적 가족상담","branches":[["개인적 차원","경험적 가족상담에서는 개인적 차원에서 체계를 다룬다"],["정서","가족구성원의 정서적 경험과 표현에 중요한 가치를 둔다"],["지금-여기","지금-여기에서 일어나는 상호작용 과정을 중시한다"],["대표 인물","대표 인물로 사티어(V. Satir)와 · 위태커(C. Whitaker)가 있다"],["인본주의","인본주의 심리학에 뿌리를 두고 있다"]]}],"8":[{"t":"tree","title":"해결중심 목표 설정","root":"목표","branches":[["구체적·행동적","구체적이고 행동적인 것을 목표로 한다 · 구체적이고 측정할 수 있는 행동을 목표로 삼는다"],["지금 여기","지금 여기에서 시작하는 것을 목표로 한다"],["내담자 중요","내담자가 중요하다고 여기는 것을 목표로 한다"],["수행의 어려움","목표 수행은 힘든 일이라는 것을 내담자가 인식하도록 한다 · 목표 수행이 힘들고 어려운 일이라고 인식하게 한다"]]},{"t":"table","title":"해결중심 단기가족치료","head":["구분","내용"],"rows":[["대처 질문","내담자가 어려움과 위기를 어떻게 극복하고 생존해 왔는지 그리고 희망을 버리지 않고 유지해 올 수 있었는지에 관하여 질문하는 동시에 생존능력을 인정하고 간접적으로 칭찬하는 기법이다"],["관점","탈이론적이고 비규범적이며 내담자의 견해를 존중한다"],["자원","내담자의 강점과 자원은 물론 증상까지도 상담에 활용한다"],["피드백 메시지","치료적 피드백 메시지는 칭찬, 연결문, 과제의 세 부분으로 구성되어 있다"],["변화","변화는 삶의 일부로서 불가피하며 계속적으로 일어난다고 가정한다"]]}],"9":[{"t":"tree","title":"이야기치료의 전제","root":"이야기치료","branches":[["정체성","인간은 사회적 관계와 문화적 맥락 속에서 자신을 이해하고 정체성을 형성해 간다"],["언어","우리가 살아가는 실재는 언어를 통해 구성되고 표현된다 · 개인의 삶은 언어를 통한 이야기로 구성되고 창출된다"],["의미 부여","인간은 자신에게 일어나는 삶의 사건을 해석하고 그에 대해 의미를 부여한다 · 세계와 인간경험은 개인이 해석하는 방식으로 존재한다"],["사회적 맥락","이야기는 사회적 맥락 속에서 만들어진다고 본다 · 우리가 살아가는 이야기는 사회적 맥락 속에서 만들어진다 · 삶의 이야기 속에는 사회적 담론과 자기정체성이 포함된다"]]},{"t":"table","title":"이야기치료의 배경과 과정","head":["구분","내용"],"rows":[["선호된 이야기","내담자가 스스로 중요하게 여기는 가치와 의미에 기반한 선호된 이야기를 발견하도록 돕는다"],["시각","포스트모더니즘과 사회구성주의적인 시각에 근거한다"],["마지막 단계","마지막 단계는 대안적 정체성을 구축하는 것이다"],["베이트슨(G. Bateson)","이야기치료는 발달 초기에 베이트슨의 영향을 받았다"]]}],"10":[{"t":"tree","title":"사회구성주의·포스트모더니즘","root":"후기 가족치료","branches":[["언어","실재(reality)는 언어를 통해 구성된다고 본다"],["객관적 실재","그 누구도 객관적인 실재를 알 수 없다고 본다"],["상호작용","실재는 상호작용을 통해 사회적으로 구성된다고 본다"],["진실","본질적인 진실이란 존재하지 않는다는 관점을 가진다"]]}],"12":[{"t":"table","title":"가족사정 도구","head":["도구","내용"],"rows":[["가계도","가족의 정서과정과 생활주기 및 가족원의 증상 등을 파악할 수 있다 · 가계도를 활용하여 가족의 정서적 역동과 패턴을 살펴본다"],["ENRICH 검사","부부관계를 파악하고 원가족을 이해하는 데 도움을 준다"],["비버즈 모델","W. Beavers · 관계 양상을 구심성과 원심성, 혼합형으로 분류한다"],["맥매스터 모델","McMaster · 문제해결, 의사소통, 역할, 정서적 반응, 상호작용, 행동통제, 일반적 기능 등으로 평가한다"],["빙산기법","가족구성원 개인의 내적 경험을 이해하기 위해 빙산기법을 활용한다"]]},{"t":"table","title":"가계도 사례","head":["대상","관계"],"rows":[["IP의 모와 외조모","갈등관계이다"],["IP의 부와 친조모","밀착된 관계이다"],["IP의 외조부모","정서적으로 단절되어 있다"],["IP의 조부와 부","알코올 문제가 이어지고 있다"]]},{"t":"flow","title":"구조적 사정","steps":["부모-자녀하위체계가 적절한 기능을 하는지 살펴본다","가족의 부적절하고 역기능적인 위계구조를 살펴본다"]}],"13":[{"t":"flow","title":"가족상담 첫 면담","steps":["상담에 참석해야 할 사람과 날짜, 장소, 시간을 구체적으로 정한다","가족들이 상담에 오기를 두려워할 때, 참여 독려전화를 하면 불참률을 낮출 수 있다","첫 면담의 주요 목표는 라포형성과 정보 수집에 있다","가족들에게 상담 참여의 필요성과 과정을 설명한다","상담자 역할의 범위와 가족의 행동규범에 관해 안내한다","구체적인 상담 목표를 설정한다"]},{"t":"tree","title":"가족상담자의 역할","root":"가족상담자","branches":[["참여","가족상담자는 가족이 참여할 수 있도록 격려한다"],["존중","가족구성원이 이해받고 존중받는 느낌을 갖도록 한다"],["합류","가족구성원 간 상호작용을 지지하고 가족체계에 합류한다"],["힘의 균형","가족상담에 참여한 모두가 동등하게 이야기하고 상호수용 가능한 의사결정을 내릴 수 있도록 힘의 균형을 유지한다"]]},{"t":"table","title":"확인할 사항","head":["확인","내용"],"rows":[["학대나 폭력","가족 내 학대나 폭력 문제가 있는지 확인한다"],["자발적 참여","Y가 상담에 자발적으로 참여하였는지 확인한다"]]}],"14":[{"t":"table","title":"가족상담자 윤리","head":["윤리","내용"],"rows":[["가치","내담자에게 상담사의 가치를 강요하지 않는다"],["비밀보장","사생활과 비밀보장의 원칙과 예외상황을 알린다"],["자기결정","내담자가 스스로 의사결정을 할 권리를 존중한다"],["이중관계","사적인 친밀관계, 성적 관계, 동업자관계 등의 관계를 맺지 않는다 · 상담자는 내담자와 사적인 친밀관계, 성적관계, 동업자관계 등을 피해야 한다"],["공정한 대우","인종, 성별, 출신국가 등에 관계없이 내담자를 공정하게 대우해야 한다"],["동의","상담을 시작하기 전에 내담자에게 자신의 권리와 책임에 대해 충분히 설명한 후 동의를 구해야 한다"]]}],"15":[{"t":"table","title":"가정폭력과 가족상담","head":["접근","내용"],"rows":[["가족체계","개인의 폭력문제도 가족문제 중의 하나로 보고 가족체계에 초점을 두고 접근한다"],["변화","가정폭력을 해결하기 위해서는 가족원간의 역기능적 상호작용 패턴과 관계구조를 변화시키는 것이 필요하다"],["보웬(M. Bowen)","가족의 폭력문제를 가족원의 낮은 자아분화 수준과 관련 있는 것으로 본다"],["이야기치료","폭력에 기여하는 가부장적 담론을 파악하고 해체하여 대안적 이야기를 구축한다"]]},{"t":"tree","title":"폭력을 목격한 자녀","root":"자녀의 영향","branches":[["수치심","심한 수치심을 느끼고 자존감 형성에 부정적 영향을 받는다"],["부적응 행동","폭력, 가출, 비행, 자살시도 등 심각한 부적응 행동을 표출할 가능성이 높아진다"],["분노","폭력을 행하는 부모뿐 아니라 폭력을 제지할 수 없는 자신의 무력함에도 분노를 느낀다"],["불안","언제 폭력이 발생할지, 자신이 폭력을 촉발시키지는 않을지 불안해하고 두려움을 느낀다"]]}],"16":[{"t":"tree","title":"중독과 가족","root":"중독가정","branches":[["동반의존자","중독가정에서 중독자에게 의존되어 있는 사람을 동반의존자라고 한다"],["가족상담적 접근","청소년 중독자의 경우 가족의 영향력이 강하기 때문에 가족상담적 접근이 필요하다"],["소외와 외로움","가족원에게서 느끼는 소외와 외로움으로 인해 다른 대상에 의존함으로써 중독에 이를 수 있다"],["장기화","중독이 장기화될수록 가정에는 우울과 절망감 등의 부정적인 정서가 심화된다"]]},{"t":"cause","title":"중독의 원인","causes":["중독의 원인을 가족의 체계나 구조에 있다고 전제한다","가족원에게서 느끼는 소외와 외로움으로 인해 다른 대상에 의존"],"result":"중독에 이르게 된다고 본다","effects":["중독문제는 가족의 부정적 상호작용 패턴에 의해 유지된다고 본다"]},{"t":"flow","title":"중독 가족상담 개입","steps":["할아버지 상실에 대한 애도작업을 한다","핵가족 정서체계에서 부모의 부부관계를 다룬다","어머니와의 친밀감 향상 등 관계 회복을 위한 작업을 한다","Y에 대해 할머니와 부모의 양육태도에서 갈등은 없는지 살핀다"]}],"17":[{"t":"flow","title":"가족구조 변화 개입","steps":["친할머니의 상실에 대한 애도작업을 한다","J의 부모에 대한 분열된 충성심을 다룬다","아버지와의 친밀감 향상을 위한 작업을 한다","어머니와의 정서적 단절 이슈에 대해 작업한다"]}],"18":[{"t":"flow","title":"청소년 문제행동 개입","steps":["학교 폭력과 가정 폭력이 있었는지 확인한다","지각과 결석 등 문제가 생길 무렵 가족내에 발생한 문제가 있었는지 확인한다","자해의 강도, 빈도 등을 확인하고 생명존중서약을 받는다","가족조각을 활용하여 가족원간의 의사소통 체계를 탐색한다"]}]};
